def annotate_equivalents():
 # These entry points perform the same task with genuinely different menu data.
 # Articles and unrelated chain pages are not declared alternate versions.
 for kind in ['home','finder','restaurants']:
  annotations=''.join('<link rel="alternate" hreflang="en-'+code+'" href="'+BASE+info[kind]+'">' for code,info in MARKETS.items())+'<link rel="alternate" hreflang="x-default" href="'+BASE+MARKETS['US'][kind]+'">'
  for info in MARKETS.values():
   route=info[kind];path='index.html' if route=='/' else route.strip('/')+'/index.html' if route.endswith('/') else route.lstrip('/')
   p=ROOT/path;text=p.read_text(encoding='utf-8');text=re.sub(r'<link rel="alternate"[^>]*>','',text);write(path,text.replace('</head>',annotations+'</head>'))

